#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxTotalSumKSelected(std::vector<std::vector<int>>& grid, int k) {
        std::vector<int> rowMaxes;
        for (auto& row : grid) {
            rowMaxes.push_back(*std::max_element(row.begin(), row.end()));
        }
        std::sort(rowMaxes.rbegin(), rowMaxes.rend());
        long long sum = 0;
        int take = std::min((int)rowMaxes.size(), k);
        for (int i = 0; i < take; ++i) sum += rowMaxes[i];
        return sum;
    }
};

import java.util.*;

class Solution {
    public long maxTotalSumKSelected(int[][] grid, int k) {
        int m = grid.length;
        int[] rowMaxes = new int[m];
        for (int i = 0; i < m; i++) {
            int mx = Integer.MIN_VALUE;
            for (int val : grid[i]) mx = Math.max(mx, val);
            rowMaxes[i] = mx;
        }
        Arrays.sort(rowMaxes);
        long sum = 0;
        int take = Math.min(m, k);
        for (int i = 0; i < take; i++) {
            sum += rowMaxes[m - 1 - i];
        }
        return sum;
    }
}

function maxTotalSumKSelected(grid, k) {
    const rowMaxes = grid.map(row => Math.max(...row));
    rowMaxes.sort((a, b) => b - a);
    let sum = 0;
    const take = Math.min(rowMaxes.length, k);
    for (let i = 0; i < take; i++) {
        sum += rowMaxes[i];
    }
    return sum;
}
